        vstd::iset::lemma_iset_new(|i: int| 0 <= i < rc_width, r);
        assert(s.contains(r));
        vstd::iset::lemma_iset_mk_map_index(s, |_i: int| 0, r);
        assert(post.ref_counts.index(r) == 0);
        // shared_pending.count(r) == 0  
        assert(post.shared_pending.count(r) == 0);
        // filter_r(empty, r).len() == 0
        assert(Self::filter_r(post.shared_guard, r) =~= Multiset::<(int, T)>::empty()) by {
            assert forall |v: (int, T)| #[trigger] Self::filter_r(post.shared_guard, r).count(v) == 0 by {
                assert(post.shared_guard =~= Multiset::<(int, T)>::empty());
            };
        };
        assert(Self::filter_r(post.shared_guard, r).len() == 0);
    };
