            // post.shared_guard = pre.shared_guard.sub(Multiset::singleton(val))
            // val.0 == r, and pre.shared_guard.count(val) >= 1 (from remove precondition)

            // Step 1: prove filter_r(post.shared_guard, r).len() == filter_r(pre.shared_guard, r).len() - 1
            assert(Self::filter_r(post.shared_guard, r).len() == 
                   Self::filter_r(pre.shared_guard, r).len() - 1) by {
                let f = |v: (int, T)| v.0 == r;
                assert(Self::filter_r(pre.shared_guard, r) == pre.shared_guard.filter(f));
                assert(Self::filter_r(post.shared_guard, r) == post.shared_guard.filter(f));
                // post.shared_guard.filter(f) =~= pre.shared_guard.filter(f).sub(singleton(val))
                assert(post.shared_guard.filter(f) =~= 
                       pre.shared_guard.filter(f).sub(Multiset::singleton(val))) by {
                    assert forall |w: (int, T)| 
                        #[trigger] post.shared_guard.filter(f).count(w) ==
                        pre.shared_guard.filter(f).sub(Multiset::singleton(val)).count(w) by {
                        if w.0 != r {
                            // w.0 != r = val.0, so w != val
                            assert(w != val);
                            assert(Multiset::<(int, T)>::singleton(val).count(w) == 0);
                        }
                    };
                };
                // pre.shared_guard.filter(f).count(val) > 0 (needed for sub axiom)
                assert(pre.shared_guard.filter(f).count(val) > 0) by {
                    // val.0 == r, so filter count = shared_guard.count(val) > 0
                    assert(pre.shared_guard.count(val) > 0); // from remove precondition
                };
                // filter(f).sub(singleton(val)).len() == filter(f).len() - 1
                assert(pre.shared_guard.filter(f).sub(Multiset::singleton(val)).len() ==
                       pre.shared_guard.filter(f).len() - 1);
            };

            // Step 2: for s != r, filter_r(post.shared_guard, s) unchanged
            assert forall |s: int| 0 <= s < post.rc_width && s != r implies
                Self::filter_r(post.shared_guard, s).len() == Self::filter_r(pre.shared_guard, s).len() by {
                let f2 = |v: (int, T)| v.0 == s;
                assert(Self::filter_r(pre.shared_guard, s) == pre.shared_guard.filter(f2));
                assert(Self::filter_r(post.shared_guard, s) == post.shared_guard.filter(f2));
                assert(post.shared_guard.filter(f2) =~= pre.shared_guard.filter(f2)) by {
                    assert forall |w: (int, T)|
                        #[trigger] post.shared_guard.filter(f2).count(w) ==
                        pre.shared_guard.filter(f2).count(w) by {
                        if w.0 == s {
                            // w.0 = s != r = val.0, so w != val
                            assert(w != val);
                            assert(Multiset::<(int, T)>::singleton(val).count(w) == 0);
                            assert(post.shared_guard.count(w) == pre.shared_guard.count(w));
                        }
                    };
                };
            };
        }
